export function loadConfig(env: Record<string, string | undefined> = process.env): Config {
  // Deploy tooling sets unset variables to '', so empty counts as unset.
  // Only the known keys are passed on; everything else in the environment is ignored.
  const input: Partial<Record<EnvKey, string>> = {}
  for (const key of KNOWN_KEYS) {
    const value = env[key]
    if (value) input[key] = value
  }

  const result = schema.safeParse(input)
  if (!result.success) {
    const invalid = [...new Set(result.error.issues.map((issue) => String(issue.path[0])))]
    throw new Error(
      'Invalid configuration: ' +
        invalid.map((key) => `${key} ${HINTS[key as EnvKey]}`).join('; '),
    )
  }

  const v = result.data
  return {
    port: v.PORT,
    databaseUrl: v.DATABASE_URL,
    logLevel: v.LOG_LEVEL,
    enableMetrics: v.ENABLE_METRICS,
    allowedOrigins: v.ALLOWED_ORIGINS,
    requestTimeoutMs: v.REQUEST_TIMEOUT_MS,
  }
}

